UPDATE Match_Apply
SET status = 1
WHERE apply_id = #{applyId}
  AND clubOwner_key = #{homeOwnerKey}
  AND clubOwner_key2 = #{opponentOwnerKey}
  AND status = 2

UPDATE Match_Apply
SET status = 6
WHERE (cmb_num = #{cmbNum}
  AND clubOwner_key = #{homeOwnerKey}
  AND clubOwner_key2 IS NOT NULL
  AND clubOwner_key2 != #{opponentOwnerKey}
  AND status = 2) OR (cmb_num = #{cmbNum} AND status = 3)

UPDATE Match_Apply
SET status = 6
WHERE apply_id = #{applyId}
  AND clubOwner_key = #{homeOwnerKey}
  AND clubOwner_key2 = #{opponentOwnerKey}
  AND status = 2

UPDATE Match_Apply
SET status = 0, cancel_reason = #{cancelReason}
WHERE apply_id = #{applyId} AND status IN (1, 2, 3)
